  const hit = [...document.querySelectorAll('*')].filter((e) => /industry|cascad|drop|menu|option|panel|dialog|select|suggest/i.test((e.className || '').toString()) && vis(e) && clean(e.innerText).length > 3);
  const out = hit.map((e) => ({cls: (e.className || '').toString().slice(0, 80), n: e.children.length, text: clean(e.innerText).slice(0, 300)}));
  out.sort((a, b) => a.text.length - b.text.length);
  return {几个: out.length, 最里面几层: out.slice(0, 6), 输入框: [...document.querySelectorAll('input')].filter(vis).map((i) => (i.placeholder || '') + '|ro=' + !!i.readOnly).slice(0, 10)};
})()
